import re

_LABEL = re.compile(r"[a-z_][a-z0-9_]*")
_INT = re.compile(r"-?[0-9]+")
_NOARG = {"pop", "dup", "swap", "over", "add", "sub", "mul", "div", "mod", "neg", "eq", "lt", "gt", "not", "ret", "in", "out", "halt"}
_JUMPS = {"jmp", "jz", "jnz", "call"}
_MIN, _MAX = -2147483648, 2147483647


def _wrap(v):
    v &= 0xFFFFFFFF
    return v - (1 << 32) if v >= (1 << 31) else v


def _load(program):
    labels, ins = {}, []
    for raw in program:
        line = raw.strip(" \t")
        if not line or line.startswith("#"):
            continue
        if line.endswith(":"):
            name = line[:-1]
            if not _LABEL.fullmatch(name) or name in labels:
                raise ValueError("bad label")
            labels[name] = len(ins)
            continue
        op, sep, arg = line.partition(" ")
        if op == "push":
            if not sep or not _INT.fullmatch(arg) or not (_MIN <= int(arg) <= _MAX):
                raise ValueError("bad push")
            ins.append((op, int(arg)))
        elif op in _JUMPS:
            if not sep or not _LABEL.fullmatch(arg):
                raise ValueError("bad jump")
            ins.append((op, arg))
        elif op in _NOARG and not sep:
            ins.append((op, None))
        else:
            raise ValueError("bad instruction")
    for op, arg in ins:
        if op in _JUMPS and arg not in labels:
            raise ValueError("unknown label")
    return ins, labels


def _exec(program, inp):
    ins, labels = _load(program)
    stack, calls, out = [], [], []
    pc = steps = pos = 0

    def pop():
        if not stack:
            raise ValueError("stack underflow")
        return stack.pop()

    def push(v):
        if len(stack) >= 256:
            raise ValueError("stack overflow")
        stack.append(v)

    while pc < len(ins):
        steps += 1
        if steps > 10000:
            raise ValueError("step limit")
        op, arg = ins[pc]
        pc += 1
        if op == "push":
            push(arg)
        elif op == "pop":
            pop()
        elif op == "dup":
            a = pop()
            push(a)
            push(a)
        elif op == "swap":
            b = pop()
            a = pop()
            push(b)
            push(a)
        elif op == "over":
            b = pop()
            a = pop()
            push(a)
            push(b)
            push(a)
        elif op in ("add", "sub", "mul", "div", "mod", "eq", "lt", "gt"):
            b = pop()
            a = pop()
            if op == "add":
                push(_wrap(a + b))
            elif op == "sub":
                push(_wrap(a - b))
            elif op == "mul":
                push(_wrap(a * b))
            elif op in ("div", "mod"):
                if b == 0:
                    raise ValueError("division by zero")
                q = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    q = -q
                push(_wrap(q) if op == "div" else _wrap(a - b * q))
            elif op == "eq":
                push(1 if a == b else 0)
            elif op == "lt":
                push(1 if a < b else 0)
            else:
                push(1 if a > b else 0)
        elif op == "neg":
            push(_wrap(-pop()))
        elif op == "not":
            push(1 if pop() == 0 else 0)
        elif op == "jmp":
            pc = labels[arg]
        elif op in ("jz", "jnz"):
            x = pop()
            if (x == 0) == (op == "jz"):
                pc = labels[arg]
        elif op == "call":
            if len(calls) >= 64:
                raise ValueError("call stack overflow")
            calls.append(pc)
            pc = labels[arg]
        elif op == "ret":
            if not calls:
                raise ValueError("ret without call")
            pc = calls.pop()
        elif op == "in":
            if pos >= len(inp):
                raise ValueError("input exhausted")
            push(inp[pos])
            pos += 1
        elif op == "out":
            out.append(pop())
        elif op == "halt":
            break
    return out, steps


def run(program, input):
    return _exec(program, input)[0]


def steps(program, input):
    return _exec(program, input)[1]


def count_ops(program):
    return len(_load(program)[0])


def disasm(program):
    ins, labels = _load(program)
    out = []
    for i, (op, arg) in enumerate(ins):
        if op in _JUMPS:
            out.append("%d: %s %d" % (i, op, labels[arg]))
        elif arg is not None:
            out.append("%d: %s %d" % (i, op, arg))
        else:
            out.append("%d: %s" % (i, op))
    return out

