package minivm

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var errVM = errors.New("minivm: error")

type instr struct {
	op     string
	arg    int32
	target int
	label  string
}

func isLabel(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		lower := (c >= 'a' && c <= 'z') || c == '_'
		digit := c >= '0' && c <= '9'
		if i == 0 && !lower {
			return false
		}
		if !lower && !digit {
			return false
		}
	}
	return true
}

func isInt(s string) bool {
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

var noArg = map[string]bool{"pop": true, "dup": true, "swap": true, "over": true, "add": true, "sub": true, "mul": true, "div": true,
	"mod": true, "neg": true, "eq": true, "lt": true, "gt": true, "not": true, "ret": true, "in": true, "out": true, "halt": true}
var jumps = map[string]bool{"jmp": true, "jz": true, "jnz": true, "call": true}

func load(program []string) ([]instr, error) {
	labels := map[string]int{}
	var ins []instr
	for _, raw := range program {
		line := strings.Trim(raw, " \t")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasSuffix(line, ":") {
			name := line[:len(line)-1]
			if _, dup := labels[name]; dup || !isLabel(name) {
				return nil, errVM
			}
			labels[name] = len(ins)
			continue
		}
		op, arg, hasArg := strings.Cut(line, " ")
		switch {
		case op == "push":
			if !hasArg || !isInt(arg) {
				return nil, errVM
			}
			v, err := strconv.ParseInt(arg, 10, 32)
			if err != nil {
				return nil, errVM
			}
			ins = append(ins, instr{op: op, arg: int32(v)})
		case jumps[op]:
			if !hasArg || !isLabel(arg) {
				return nil, errVM
			}
			ins = append(ins, instr{op: op, label: arg})
		case noArg[op] && !hasArg:
			ins = append(ins, instr{op: op})
		default:
			return nil, errVM
		}
	}
	for i := range ins {
		if jumps[ins[i].op] {
			t, ok := labels[ins[i].label]
			if !ok {
				return nil, errVM
			}
			ins[i].target = t
		}
	}
	return ins, nil
}

func exec(program []string, input []int32) ([]int64, int64, error) {
	ins, err := load(program)
	if err != nil {
		return nil, 0, err
	}
	var stack []int32
	var calls []int
	out := []int64{}
	pc, steps, pos := 0, int64(0), 0
	pop := func() (int32, bool) {
		if len(stack) == 0 {
			return 0, false
		}
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		return v, true
	}
	push := func(v int32) bool {
		if len(stack) >= 256 {
			return false
		}
		stack = append(stack, v)
		return true
	}
	b2i := func(b bool) int32 {
		if b {
			return 1
		}
		return 0
	}
loop:
	for pc < len(ins) {
		steps++
		if steps > 10000 {
			return nil, 0, errVM
		}
		in := ins[pc]
		pc++
		ok := true
		switch in.op {
		case "push":
			ok = push(in.arg)
		case "pop":
			_, ok = pop()
		case "dup":
			var a int32
			if a, ok = pop(); ok {
				ok = push(a) && push(a)
			}
		case "swap":
			b, ok1 := pop()
			a, ok2 := pop()
			ok = ok1 && ok2 && push(b) && push(a)
		case "over":
			b, ok1 := pop()
			a, ok2 := pop()
			ok = ok1 && ok2 && push(a) && push(b) && push(a)
		case "add", "sub", "mul", "div", "mod", "eq", "lt", "gt":
			b, ok1 := pop()
			a, ok2 := pop()
			if !ok1 || !ok2 {
				ok = false
				break
			}
			var r int32
			switch in.op {
			case "add":
				r = a + b
			case "sub":
				r = a - b
			case "mul":
				r = a * b
			case "div", "mod":
				if b == 0 {
					return nil, 0, errVM
				}
				if in.op == "div" {
					r = a / b
				} else {
					r = a % b
				}
			case "eq":
				r = b2i(a == b)
			case "lt":
				r = b2i(a < b)
			case "gt":
				r = b2i(a > b)
			}
			ok = push(r)
		case "neg":
			var a int32
			if a, ok = pop(); ok {
				ok = push(-a)
			}
		case "not":
			var a int32
			if a, ok = pop(); ok {
				ok = push(b2i(a == 0))
			}
		case "jmp":
			pc = in.target
		case "jz", "jnz":
			var a int32
			if a, ok = pop(); ok && (a == 0) == (in.op == "jz") {
				pc = in.target
			}
		case "call":
			if len(calls) >= 64 {
				ok = false
			} else {
				calls = append(calls, pc)
				pc = in.target
			}
		case "ret":
			if len(calls) == 0 {
				ok = false
			} else {
				pc = calls[len(calls)-1]
				calls = calls[:len(calls)-1]
			}
		case "in":
			if pos >= len(input) {
				ok = false
			} else {
				ok = push(input[pos])
				pos++
			}
		case "out":
			var a int32
			if a, ok = pop(); ok {
				out = append(out, int64(a))
			}
		case "halt":
			break loop
		}
		if !ok {
			return nil, 0, errVM
		}
	}
	return out, steps, nil
}

func Run(program []string, input []int32) ([]int64, error) {
	out, _, err := exec(program, input)
	return out, err
}

func Steps(program []string, input []int32) (int64, error) {
	_, n, err := exec(program, input)
	return n, err
}

func CountOps(program []string) (int64, error) {
	ins, err := load(program)
	return int64(len(ins)), err
}

func Disasm(program []string) ([]string, error) {
	ins, err := load(program)
	if err != nil {
		return nil, err
	}
	out := []string{}
	for i, in := range ins {
		switch {
		case jumps[in.op]:
			out = append(out, fmt.Sprintf("%d: %s %d", i, in.op, in.target))
		case in.op == "push":
			out = append(out, fmt.Sprintf("%d: push %d", i, in.arg))
		default:
			out = append(out, fmt.Sprintf("%d: %s", i, in.op))
		}
	}
	return out, nil
}

